   234			return t, numEntriesToPop
   235		}
   236		q.consumerMu.Lock()
   237		// numEntriesToPop is a function of index and tail. The value of tail cannot
   238		// change since consumerMu is held.
   239		tail, numEntriesToPop := tailEntriesToPop()
   240		if numEntriesToPop <= 0 {
   241			q.consumerMu.Unlock()
   242			return 0
   243		}
   244		var b []poppedEntry
   245		if numEntriesToPop <= len(buf) {
   246			b = buf[:numEntriesToPop]
   247		} else {
   248			// Do allocation before acquiring the mutex.
   249			b = make([]poppedEntry, numEntriesToPop)
   250		}
   251		q.mu.RLock()
   252		n := len(q.buffer)
   253		for i := 0; i < numEntriesToPop; i++ {
   254			// Grab the popped entries before incrementing tail, since that will
   255			// release those buffer slots to the producer.
   256			idx := (i + int(tail)) % n
   257			b[i] = poppedEntry{
